import{_ as a,o as e,c as d,ag as i}from"./chunks/framework.DaCm-iTo.js";const k=JSON.parse('{"title":"锻造历史记录","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/history.md","filePath":"modules/forge/history.md","lastUpdated":null}'),s={name:"modules/forge/history.md"};function l(o,t,r,h,n,c){return e(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="锻造历史记录" tabindex="-1">锻造历史记录 <a class="header-anchor" href="#锻造历史记录" aria-label="Permalink to &quot;锻造历史记录&quot;">​</a></h1><p>Forge 按玩家保存锻造记录，用于统计配方使用次数、驱动品质保底计数和支撑锻造相关占位符。</p><h2 id="配置位置" tabindex="-1">配置位置 <a class="header-anchor" href="#配置位置" aria-label="Permalink to &quot;配置位置&quot;">​</a></h2><p>历史记录位于 <code>config.yml</code> 的 <code>history</code> 节点：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">history</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto_save</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 自动保存间隔，6000 tick = 5 分钟</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  save_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6000</span></span></code></pre></div><h2 id="字段说明" tabindex="-1">字段说明 <a class="header-anchor" href="#字段说明" aria-label="Permalink to &quot;字段说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>boolean</td><td><code>true</code></td><td>是否启用锻造历史记录。</td></tr><tr><td><code>auto_save</code></td><td>boolean</td><td><code>true</code></td><td>是否定时保存玩家数据。</td></tr><tr><td><code>save_interval</code></td><td>integer</td><td><code>6000</code></td><td>自动保存间隔，单位 tick。6000 tick 约为 5 分钟。</td></tr></tbody></table><blockquote><p><code>enabled</code> 与 <code>auto_save</code> 任一为 false 时，定时自动保存任务不会被调度。</p></blockquote><h2 id="存储位置" tabindex="-1">存储位置 <a class="header-anchor" href="#存储位置" aria-label="Permalink to &quot;存储位置&quot;">​</a></h2><p>玩家数据保存在 <code>plugins/EmakiForge/data/&lt;玩家UUID&gt;.yml</code>，每名玩家一个文件。</p><h2 id="记录内容" tabindex="-1">记录内容 <a class="header-anchor" href="#记录内容" aria-label="Permalink to &quot;记录内容&quot;">​</a></h2><p>每个玩家文件按配方 ID 记录：</p><table tabindex="0"><thead><tr><th>信息</th><th>用途</th></tr></thead><tbody><tr><td>玩家 UUID</td><td>文件名与文件内 <code>uuid</code> 字段，定位数据归属。</td></tr><tr><td>配方 ID</td><td>按配方分组记录锻造数据。</td></tr><tr><td>锻造次数</td><td>支撑 <code>%emakiforge_craft_count_&lt;recipe_id&gt;%</code> 与总次数统计。</td></tr><tr><td>最后锻造时间</td><td>字段 <code>last_crafted_at</code>，支撑 <code>%emakiforge_last_crafted%</code>。</td></tr><tr><td>保底计数</td><td>品质保底的连续计数，按玩家 + 配方维度记录。</td></tr></tbody></table><h2 id="与品质保底的关系" tabindex="-1">与品质保底的关系 <a class="header-anchor" href="#与品质保底的关系" aria-label="Permalink to &quot;与品质保底的关系&quot;">​</a></h2><p>保底计数器就保存在玩家数据文件中，两者直接相关：</p><ul><li>每次锻造结果低于保底最低品质时，保底计数 +1。</li><li>计数达到阈值后触发保底，并重置计数。</li><li>保底触发条件与阈值见<a href="./quality.html">品质系统</a>。</li></ul><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li>正式服建议开启 <code>enabled</code> 和 <code>auto_save</code>。</li><li>高并发服务器可适当提高 <code>save_interval</code>，减少频繁写盘。</li><li>赛季服或活动服可以在活动结束后归档 <code>data/</code> 目录，用于统计配方产出。</li></ul><h2 id="排查建议" tabindex="-1">排查建议 <a class="header-anchor" href="#排查建议" aria-label="Permalink to &quot;排查建议&quot;">​</a></h2><ul><li>数据未保存：检查 <code>enabled</code>、<code>auto_save</code> 和 <code>data/</code> 目录权限。</li><li>玩家数据加载失败时，该玩家会话会保持只读以保护已有文件，控制台会输出对应警告。</li><li>保底表现异常：先用 <code>%emakiforge_guarantee_&lt;recipe_id&gt;%</code> 确认当前计数，再核对配方与全局的保底配置。</li><li>重载后数据异常：确认自动保存间隔，必要时在维护前先停服等待数据落盘。</li></ul>`,20)])])}const u=a(s,[["render",l]]);export{k as __pageData,u as default};
